/* Campus social, points and redemption demo. All changes remain in this browser. */
const uid=()=>crypto.randomUUID();
const people={lin:{name:'林间',initial:'林',school:'浙江大学',bio:'用镜头收集日常，也想认识镜头外的你。',interests:['摄影','音乐'],color:'peach',frame:'sunset'},chen:{name:'陈一舟',initial:'舟',school:'上海交通大学',bio:'写代码，也做一些有趣的小东西。寻找愿意一起做项目的人。',interests:['Web3','设计'],color:'mint',frame:'orbit'},xia:{name:'夏小满',initial:'夏',school:'复旦大学',bio:'周末去跑步，跑完喝咖啡。',interests:['跑步','咖啡'],color:'lilac',frame:''}};
const circles=[{id:'photo',name:'校园摄影散步社',interest:'摄影',symbol:'◎',color:'peach',description:'不必有专业设备，一起发现校园的光。',members:128},{id:'music',name:'耳机里的同路人',interest:'音乐',symbol:'♫',color:'lilac',description:'交换歌单，约一场草坪音乐会。',members:206},{id:'build',name:'校园创意实验室',interest:'Web3',symbol:'⌘',color:'mint',description:'让想法落地，和不同专业的伙伴一起创造。',members:89},{id:'run',name:'课后一起跑',interest:'跑步',symbol:'↗',color:'lime',description:'不用跑得快，只要一起出发。',members:164}];
const initialPosts=[{id:'p1',author:'lin',circle:'photo',title:'把校园的秋天，装进一张照片里。',text:'今天傍晚的光刚刚好。想找几位同学，周末一起在校园里散步拍照，不用专业相机，手机也可以！',art:'sunset',likes:24,event:'coffee',time:'20 分钟前'}, {id:'p2',author:'chen',circle:'build',title:'有个小想法：做一本属于校园的声音地图。',text:'记录食堂的喧闹、图书馆外的风，还有社团排练的声音。已有前端原型，想找对声音和交互设计感兴趣的朋友一起做。',art:'',likes:18,event:'',time:'1 小时前'}, {id:'p3',author:'xia',circle:'run',title:'慢一点也没关系，我们一起跑到终点。',text:'第一次跑完 5 公里！比起配速，更开心的是认识了三个新朋友。下次见面，我们先去喝一杯咖啡吧。',art:'run',likes:36,event:'run',time:'2 小时前'}];
const initialTeams=[{id:'t1',author:'chen',title:'一起做一份校园声音地图',description:'把声音放进地图，做一个可以听见校园日常的小作品。现有前端开发与产品各一人，希望一起完成可体验的原型。',skill:'视觉设计 / 声音采集',duration:'2 周 · 每周 3 小时',pay:'兴趣共创，无报酬',cross:true,school:'上海交通大学'}, {id:'t2',author:'lin',title:'周末校园短片，寻找镜头里的主角',description:'拍一支三分钟的校园生活短片，记录下课后的自由时间。作品会用于校园艺术展，发布前共同确认。',skill:'表演 / 摄影 / 剪辑',duration:'本周末 · 半天',pay:'兴趣共创，无报酬',cross:true,school:'浙江大学'}];
const products=[{id:'coffee-coupon',name:'给课间一杯好咖啡',brand:'SLOW COFFEE',category:'品牌福利',cost:150,stock:30,symbol:'☕',color:'peach',type:'coupon',detail:'中杯美式兑换券一张。演示领取地点：校园咖啡快闪店。无需额外消费；体验订单长期有效。'}, {id:'sunset',name:'日落放映机 · 头像框',brand:'CAMPUS ORIGINALS',category:'个性装扮',cost:80,stock:999,symbol:'✺',color:'sunset',type:'frame',detail:'暖橙色头像框。兑换后可在个人主页装扮栏穿戴，并同步展示在动态、评论和个人名片中。'}, {id:'orbit',name:'环游星际 · 头像框',brand:'CAMPUS ORIGINALS',category:'个性装扮',cost:120,stock:999,symbol:'✳',color:'lilac',type:'frame',detail:'紫色星轨头像框。表达你的兴趣与个性，不代表认证或活动参与经历。'}, {id:'workshop',name:'周末手冲 · 体验席位',brand:'SLOW COFFEE LAB',category:'校园体验',cost:200,stock:8,symbol:'◕',color:'mint',type:'coupon',detail:'手冲工作坊单人体验名额，含材料。演示场次：12 月 12 日 14:00，校园活动中心。'}, {id:'tote',name:'把灵感装进口袋',brand:'BLANK STUDIO',category:'品牌福利',cost:300,stock:15,symbol:'▧',color:'lime',type:'coupon',detail:'联名帆布袋一个。演示领取地点：校园艺术中心服务台，仅支持现场领取。'}, {id:'starlight',name:'星光来信 · 主页背景',brand:'CAMPUS ORIGINALS',category:'个性装扮',cost:180,stock:999,symbol:'✧',color:'night',type:'background',detail:'为个人主页点亮一片星空。兑换后在装扮栏切换，不影响头像框。'}];
products.push(...STARTER_OUTFITS);
const freshSocial=()=>({version:2,ledger:[{id:'welcome-demo',amount:180,label:'新版体验积分',time:'首次体验'}],orders:[],owned:[],equipped:'',background:'',interests:['摄影','音乐'],joinedCircles:[],posts:[],teams:[],likes:[],comments:{},applications:{},connections:[],blocked:[],reports:[],showSchool:true});
let social=freshSocial();
try{const saved=JSON.parse(localStorage.getItem('campusT-demo-v1'))?.social;if(saved?.version===2)social={...social,...saved};}catch{}
social.owned=[...new Set([...(Array.isArray(social.owned)?social.owned:[]),...STARTER_OUTFITS.map(p=>p.id)])];
state.social=social;
function points(){return social.ledger.reduce((n,x)=>n+x.amount,0);}
function grantEventPoints(event){const id='activity-'+event.id;if(!social.ledger.some(x=>x.id===id))social.ledger.push({id,amount:100,label:'完成活动 · '+event.title,time:'刚刚'});}
allEvents().filter(e=>state.progress[e.id]==='claimed').forEach(grantEventPoints);
save();
let communityTab='feed',circleFilter='',shopFilter='全部奖励',mineTab='overview',selectedProduct=null;
const currentProfile=()=>({name:'校园探索家',initial:'K',school:social.showSchool?'浙江大学':'校园未公开',bio:'把生活过成喜欢的样子，和同频的人一起创造。',interests:social.interests,color:'lilac',frame:window.campusNFT?.frame()||social.equipped});
const person=id=>id==='me'?currentProfile():people[id];
const tags=items=>`<div class="tags">${items.map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</div>`;
const avatar=(id,large=false)=>{const p=person(id);return `<span class="social-avatar ${p.color} ${p.frame?'frame-'+p.frame:''} ${large?'large':''}">${p.initial}</span>`;};
const author=id=>`<button class="author" data-person="${id}">${avatar(id)}<span><strong>${escapeHTML(person(id).name)}</strong><small>${escapeHTML(person(id).school)}</small></span></button>`;
const blank=(title,text)=>`<div class="empty"><div class="empty-symbol">✧</div><h3>${title}</h3><p>${text}</p></div>`;
const tabs=(items,selected,attribute)=>`<div class="tab-bar" role="group">${items.map(([key,label])=>`<button class="${selected===key?'selected':''}" ${attribute}="${key}" aria-pressed="${selected===key}">${label}</button>`).join('')}</div>`;
function modal(title,body){const d=$('#social-dialog');d.innerHTML=`<div class="modal-top"><div><span class="eyebrow">CAMPUS CONNECTIONS</span><h2>${title}</h2></div><button class="icon-button" data-close aria-label="关闭">✕</button></div>${body}`;if(!d.open)d.showModal();}
function renderExtended(){
 if(page==='rewards'){page='me';mineTab='collection';history.replaceState(null,'','#me');}
 if(!['campus','shop','me'].includes(page))return false;
 const labels={campus:'校园社区',shop:'奖励商城',me:'我的校园名片'};$('#breadcrumb').textContent=labels[page];document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 $('#content').innerHTML=page==='campus'?communityView():page==='shop'?shopView():meView();return true;
}
function sidePanel(){return `<aside class="community-aside"><div class="panel mini-profile"><div class="mini-cover"></div>${avatar('me',true)}<h3>校园探索家</h3><p>让同好，从认识你开始。</p>${tags(social.interests)}<button class="outline full" data-nav="me">看看我的名片</button></div><div class="panel points-widget"><span class="eyebrow">YOUR CAMPUS POINTS</span><h3>${points()} <small>积分</small></h3><p>每一次参与，都有新的回响。</p><button class="text-button" data-nav="shop">去兑换一份小确幸</button></div><div class="panel guidelines"><h3>这里的默契</h3><p>尊重不同的兴趣，先征得同意再联系。分享真实经历，让合作的期待更明确。</p><small>本页人物与内容为演示；发布与互动仅保存在本机。</small></div></aside>`;}
function communityView(){return heading('同频的人，就在下一次相遇。','分享热爱，找到搭子，把一个人的灵感变成一群人的作品。',`<button class="primary" data-compose="${communityTab==='teams'?'team':'post'}">＋ ${communityTab==='teams'?'发起组队':'发布动态'}</button>`)+`<section class="community-hero"><div><span class="eyebrow">BETTER, TOGETHER.</span><h2>校园很大，<br>你的同好<span>并不遥远。</span></h2><p>从一句「我也喜欢」，到一次「一起试试」。</p><div class="hero-actions"><button class="hero-button" data-community-tab="teams">寻找我的搭子</button><span>兴趣相遇 · 灵感共创</span></div></div><div class="friend-art" aria-hidden="true"><span class="friend one">✿</span><span class="friend two">✳</span><span class="friend three">◎</span><i>LET’S MAKE SOMETHING.</i></div></section><div class="community-layout"><section>${tabs([['feed','校园动态'],['teams','找搭子'],['circles','兴趣圈']],communityTab,'data-community-tab')}<div class="scope-line"><span>${state.school==='all'?'跨校园交流':escapeHTML(state.school)+' · 校园视角'}</span>${circleFilter?`<button class="text-button" data-clear-circle>清除「${escapeHTML(circles.find(c=>c.id===circleFilter)?.name||'圈子')}」筛选</button>`:'<span>由共同的热爱连接</span>'}</div>${communityTab==='feed'?feedView():communityTab==='teams'?teamsView():circlesView()}</section>${sidePanel()}</div>`;}
function allPosts(){return [...social.posts,...initialPosts].filter(p=>!social.blocked.includes(p.author));}
function postCard(p){const comments=social.comments[p.id]||[];const circle=circles.find(c=>c.id===p.circle);return `<article class="panel post"><div class="post-heading">${author(p.author)}<span class="post-time">${escapeHTML(p.time)}</span></div>${circle?`<button class="circle-label" data-open-circle="${circle.id}"># ${circle.name}</button>`:''}<h3>${escapeHTML(p.title)}</h3><p class="post-text">${escapeHTML(p.text)}</p>${p.art?`<div class="post-art ${p.art}" aria-hidden="true"><span>${p.art==='sunset'?'AFTER CLASS,<br>BEFORE SUNSET.':'SLOW PACE.<br>GOOD COMPANY.'}</span><i>${p.art==='sunset'?'◒':'↗'}</i></div>`:''}${p.event?`<button class="linked-event" data-event="${p.event}">${icon('calendar')} 聊聊这场活动 · ${escapeHTML(seed.find(e=>e.id===p.event)?.title.split(' · ')[0]||'校园活动')}</button>`:''}<div class="post-actions"><button data-like="${p.id}" aria-pressed="${social.likes.includes(p.id)}" class="${social.likes.includes(p.id)?'liked':''}">♡ ${p.likes+(social.likes.includes(p.id)?1:0)} 喜欢</button><button data-comments="${p.id}">◯ ${comments.length} 条交流</button><button data-person="${p.author}">查看名片</button></div></article>`;}
function feedView(){const list=allPosts().filter(p=>(!circleFilter||p.circle===circleFilter)&&(state.school==='all'||person(p.author).school===state.school));return `<button class="composer panel" data-compose="post">${avatar('me')}<span>今天有什么想分享给同好？</span><span class="compose-plus">＋</span></button>${list.length?list.map(postCard).join(''):blank('这里等你来开场','发布一条动态，或者切换校园与兴趣圈筛选。')}`;}
function teamsView(){const teams=[...social.teams,...initialTeams].filter(t=>!social.blocked.includes(t.author)&&(state.school==='all'||t.school===state.school||t.cross));return teams.length?teams.map(t=>`<article class="panel team-card"><div class="post-heading">${author(t.author)}<span class="pill">${t.cross?'跨校招募':'本校招募'}</span></div><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.description)}</p><dl><div><dt>寻找伙伴</dt><dd>${escapeHTML(t.skill)}</dd></div><div><dt>时间投入</dt><dd>${escapeHTML(t.duration)}</dd></div><div><dt>合作方式</dt><dd>${escapeHTML(t.pay)}</dd></div></dl><div class="team-footer"><span>${t.author==='me'?'我的招募 · 已发布':social.applications[t.id]?'申请已保存 · 演示待回应':'先聊聊想法，再决定一起出发'}</span><button class="primary" data-apply="${t.id}" ${t.author==='me'||social.applications[t.id]?'disabled':''}>${social.applications[t.id]?'已申请':'申请加入'}</button></div></article>`).join(''):blank('还没有适合的招募','发起你的第一个共创项目，或切换至所有校园。');}
function circlesView(){return `<div class="circle-grid">${circles.map(c=>`<article class="panel circle-card"><div class="circle-symbol ${c.color}">${c.symbol}</div><h3>${c.name}</h3><p>${c.description}</p><small>${c.members+(social.joinedCircles.includes(c.id)?1:0)} 位同好 · 跨校园</small><div class="circle-actions"><button class="${social.joinedCircles.includes(c.id)?'outline':'primary'}" data-join-circle="${c.id}">${social.joinedCircles.includes(c.id)?'已加入 · 退出':'加入兴趣圈'}</button><button class="text-button" data-open-circle="${c.id}">看看动态</button></div></article>`).join('')}</div>`;}
function remaining(product){return product.stock-social.orders.filter(o=>o.product===product.id&&o.status!=='cancelled').length;}
function shopView(){const filtered=products.filter(p=>!p.eventOnly&&!p.starter).filter(p=>shopFilter==='全部奖励'||p.category===shopFilter);return heading('让每一次参与，都有小确幸。','用校园积分兑换品牌福利、精彩体验，还有属于你的个人风格。',`<button class="outline" data-mine-tab="orders">我的兑换</button>`)+`<section class="shop-hero"><div><span class="eyebrow">GOOD MOMENTS, GREAT REWARDS.</span><h2>把热爱，兑换成<span>日常的惊喜。</span></h2><p>一杯咖啡，一次体验，一枚专属头像框。</p><button class="hero-button" data-nav="explore">参加活动赚积分</button></div><div class="points-card"><span>我的可用积分</span><strong>${points()} <small>PTS</small></strong><button data-mine-tab="ledger">查看积分明细</button></div></section><p class="shop-disclaimer">体验积分：首次赠送 180 分，完成活动获得 100 分。奖品、库存和核销均为本机模拟，不可提现。</p>${tabs(['全部奖励','品牌福利','校园体验','个性装扮'].map(x=>[x,x]),shopFilter,'data-shop-filter')}<div class="shop-grid">${filtered.map(p=>`<article class="product-card"><div class="product-art ${p.color}"><span class="product-type">${p.category}</span><span class="product-symbol">${p.symbol}</span><span class="product-brand">${p.brand}</span></div><div class="product-body"><h3>${p.name}</h3><p>${p.type==='coupon'?`剩余 ${remaining(p)} 份 · 现场领取`:'兑换即可使用 · 全社区展示'}</p><div class="product-footer"><strong>${p.cost} <small>积分</small></strong><button class="${social.owned.includes(p.id)?'outline':'primary'}" data-product="${p.id}">${social.owned.includes(p.id)?'已拥有':'查看兑换'}</button></div></div></article>`).join('')}</div>`;}
function showProduct(id){const p=products.find(p=>p.id===id);if(!p)return;selectedProduct=id;const owned=social.owned.includes(id);modal('兑换一份小确幸',`<div class="product-art modal-product ${p.color}"><span class="product-symbol">${p.symbol}</span></div><h3>${p.name}</h3><p class="modal-description">${p.detail}</p><div class="redeem-summary"><span>所需积分 <strong>${p.cost}</strong></span><span>当前余额 <strong>${points()}</strong></span></div><p class="muted">${p.type==='coupon'?'未核销前可以取消，积分与名额会退回。核销只能完成一次。':'数字装扮即时到账，不可取消。每款仅可兑换一次。'}</p><button class="primary full" data-redeem="${id}" ${owned||remaining(p)<=0||points()<p.cost?'disabled':''}>${owned?'已拥有这件装扮':remaining(p)<=0?'已兑完':points()<p.cost?`还差 ${p.cost-points()} 积分`:`确认兑换 · ${p.cost} 积分`}</button><p class="form-note">仅演示兑换流程，不会生成真实品牌兑换凭证。</p>`);}
function redeem(id){const p=products.find(p=>p.id===id);if(!p||points()<p.cost||remaining(p)<=0||social.owned.includes(id))return false;const order={id:uid(),product:id,status:p.type==='coupon'?'ready':'delivered',code:'DEMO-'+uid().slice(0,8).toUpperCase()};social.orders.unshift(order);social.ledger.push({id:'redeem-'+order.id,amount:-p.cost,label:'兑换 · '+p.name,time:'刚刚'});if(p.type!=='coupon')social.owned.push(id);save();return order;}
function cancelOrder(id){const o=social.orders.find(o=>o.id===id);if(!o||o.status!=='ready')return false;o.status='cancelled';social.ledger.push({id:'refund-'+o.id,amount:products.find(p=>p.id===o.product).cost,label:'取消兑换 · 积分退回',time:'刚刚'});save();return true;}
function useOrder(id){const o=social.orders.find(o=>o.id===id);if(!o||o.status!=='ready')return false;o.status='used';save();return true;}
function meView(){return heading('你的热爱，值得被看见。','让兴趣成为开场白，让经历成为连接彼此的线索。',`<button class="outline" data-edit-profile>编辑兴趣</button>`)+`<section class="profile-cover ${profileCoverClass()}"><span class="cover-label">MY CAMPUS, MY STORY.</span><div class="cover-ornament" aria-hidden="true">✳</div></section><section class="profile-summary"><div>${avatar('me',true)}<h2>校园探索家 <span>体验账号</span></h2><p>${currentProfile().school} · ${escapeHTML(currentProfile().bio)}</p>${tags(social.interests)}</div><div class="profile-numbers"><button data-mine-tab="ledger"><strong>${points()}</strong><span>可用积分</span></button><button data-mine-tab="events"><strong>${Object.keys(state.progress).length}</strong><span>参与活动</span></button><button data-community-tab="circles"><strong>${social.joinedCircles.length}</strong><span>兴趣圈</span></button></div></section>${tabs([['overview','个人名片'],['events','我的活动'],['orders','兑换订单'],['dress','我的装扮'],['collection','活动徽章'],['ledger','积分明细']],mineTab,'data-mine-tab')}<div class="mine-content">${mineContent()}</div><button class="mobile-brand" data-nav="brand">品牌合作 · 发起校园活动</button>`;}
function mineContent(){
 if(mineTab==='overview')return `<div class="profile-columns"><div class="panel"><h3>关于我</h3><p class="modal-description">${currentProfile().bio}</p><h4>我想找到这样的伙伴</h4>${tags(social.interests)}<button class="outline" data-community-tab="teams">去找搭子</button><label class="privacy-setting"><input type="checkbox" id="school-privacy" ${social.showSchool?'checked':''}>在公开名片中展示我的校园</label></div><div class="panel"><h3>我的校园足迹</h3><p class="modal-description">${social.posts.length} 条动态 · ${social.teams.length} 次组队发起 · ${Object.keys(social.applications).length} 次组队申请</p><p class="muted">装扮表达喜好；活动徽章记录参与经历。兴趣圈加入后可在社区查看动态。</p><button class="outline" data-community-tab="feed">回到社区分享</button><button class="text-button" data-privacy-manage>管理屏蔽与申请</button></div></div>${social.posts.length?'<h3 class="section-spacer">我的分享</h3>'+social.posts.map(postCard).join(''):''}`;
 if(mineTab==='events'){const list=allEvents().filter(e=>state.progress[e.id]);return `<div class="grid">${list.length?list.map(card).join(''):empty('第一场相遇，从这里开始','参加活动，完成签到后领取 100 积分。')}</div>`;}
 if(mineTab==='orders')return social.orders.length?social.orders.map(o=>{const p=products.find(p=>p.id===o.product);return `<article class="panel order"><div class="order-art ${p.color}">${p.symbol}</div><div class="order-info"><h3>${p.name}</h3><p>${p.cost} 积分 · ${o.status==='ready'?'待领取':o.status==='used'?'已核销':o.status==='cancelled'?'已取消 · 积分已退回':'装扮已到账'}</p>${o.status==='ready'?`<code>${o.code}</code><small>演示核销码 · 无真实兑换效力</small>`:''}</div><div class="order-actions">${o.status==='ready'?`<button class="primary" data-use-order="${o.id}">模拟现场核销</button><button class="text-button" data-cancel-order="${o.id}">取消并退回积分</button>`:o.status==='delivered'?'<button class="outline" data-mine-tab="dress">去装扮</button>':''}</div></article>`;}).join(''):blank('还没有兑换记录','去奖励商城，用积分兑换第一份福利。');
 if(mineTab==='dress')return wardrobeView();
 if(mineTab==='collection'){const claimed=allEvents().filter(e=>state.progress[e.id]==='claimed'&&e.reward!=='token');return `<div class="info-banner">活动徽章来自完成活动；NFT 为演示收藏，尚未写入 Monad。</div><div class="grid">${claimed.length?claimed.map(e=>`<article class="collection"><div class="collection-art">${escapeHTML(e.shape)}</div><h3>${escapeHTML(e.title.split(' · ')[0])}</h3><p>活动参与凭证 · ${escapeHTML(e.school)}</p><button class="text-button" data-event="${e.id}">查看活动</button></article>`).join(''):empty('每一段经历，都有自己的徽章','完成一场含 NFT 的活动，收藏你的校园记忆。')}</div>`;}
 return `<div class="panel"><div class="ledger-heading"><h3>积分收支明细</h3><strong>${points()} <small>可用积分</small></strong></div><p class="muted">积分不可转让、不可提现；本 Demo 不设到期。活动奖励只能领取一次。</p>${[...social.ledger].reverse().map(l=>`<div class="ledger-row"><span>${escapeHTML(l.label)}<small>${escapeHTML(l.time)}</small></span><strong class="${l.amount>0?'positive':''}">${l.amount>0?'+':''}${l.amount}</strong></div>`).join('')}</div>`;
}
function showPerson(id){if(id==='me'){navigate('me');return;}const p=person(id);if(!p)return;const common=p.interests.filter(t=>social.interests.includes(t));modal('在这里，认识一个同好',`<div class="public-profile">${avatar(id,true)}<h3>${p.name}</h3><p>${p.school}</p><p>${p.bio}</p>${tags(p.interests)}</div><div class="common-box"><strong>你们的共同点</strong><p>${common.length?'都喜欢 '+common.join('、'):'你们的兴趣各不相同，也许能碰撞出新灵感。'}</p><small>兴趣来自个人填写，装扮不代表技能认证。</small></div><button class="primary full" data-connect-person="${id}" ${social.connections.includes(id)||social.blocked.includes(id)?'disabled':''}>${social.blocked.includes(id)?'已屏蔽':social.connections.includes(id)?'交流申请已保存':'申请交流'}</button><p class="form-note">交流需要对方同意。演示中只保存申请，不会向任何人发送消息。</p><div class="profile-tools"><button data-block="${id}">${social.blocked.includes(id)?'取消屏蔽':'屏蔽此用户'}</button><button data-report="${id}">举报不当内容</button></div>`);}
function showComments(id){const p=allPosts().find(p=>p.id===id);if(!p)return;modal('从一句话，开始交流',`<h3>${escapeHTML(p.title)}</h3><div class="comment-list">${(social.comments[id]||[]).map(c=>`<div class="comment">${avatar('me')}<div><strong>校园探索家</strong><p>${escapeHTML(c)}</p></div></div>`).join('')||'<p class="muted">还没有留言，成为第一个回应的人。</p>'}</div><form data-form="comment" data-post-id="${id}"><label>分享你的想法<textarea name="text" required maxlength="300" placeholder="我也喜欢……"></textarea></label><button class="primary" type="submit">发布留言</button></form>`);}
function compose(type){modal(type==='team'?'让一个想法，找到一群伙伴':'把热爱分享给同好',`<form data-form="${type}"><label>${type==='team'?'你想一起做什么？':'给这条动态起个标题'}<input name="title" maxlength="60" required placeholder="写一个具体、有趣的标题"></label><label>${type==='team'?'项目目标与当前进展':'想分享的内容'}<textarea name="text" rows="4" maxlength="600" required placeholder="说说你的想法，让同好更了解你。"></textarea></label>${type==='team'?`<label>寻找什么技能的伙伴？<input name="skill" maxlength="80" required placeholder="例如：摄影、剪辑、视觉设计"></label><label>时间投入<input name="duration" maxlength="60" required placeholder="例如：两周，每周 3 小时"></label><label>合作与报酬方式<select name="pay"><option>兴趣共创，无报酬</option><option>比赛组队，奖金按约定分配</option><option>有偿合作，沟通后确定</option></select></label><label class="check-label"><input name="cross" type="checkbox" checked>接受跨校合作</label>`:`<label>发布到哪个圈子？<select name="circle"><option value="">校园广场</option>${circles.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label>`}<p class="form-note">分享和招募仅保存在本机。发帖与点赞不会获得积分。</p><button class="primary full" type="submit">${type==='team'?'发布组队招募':'发布动态'}</button></form>`);}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b)return;const d=b.dataset;
 if(b.id==='profile')navigate('me');
 if(d.communityTab){communityTab=d.communityTab;circleFilter='';navigate('campus');}
 if(d.mineTab){mineTab=d.mineTab;navigate('me');}
 if(d.shopFilter){shopFilter=d.shopFilter;render();}
 if(d.compose)compose(d.compose);
 if(d.person)showPerson(d.person);
 if(d.openCircle){circleFilter=d.openCircle;communityTab='feed';navigate('campus');}
 if('clearCircle' in d){circleFilter='';render();}
 if(d.joinCircle){const i=social.joinedCircles.indexOf(d.joinCircle);i<0?social.joinedCircles.push(d.joinCircle):social.joinedCircles.splice(i,1);save();render();toast(i<0?'已加入兴趣圈，去和同好交流吧':'已退出兴趣圈');}
 if(d.like){const i=social.likes.indexOf(d.like);i<0?social.likes.push(d.like):social.likes.splice(i,1);save();render();}
 if(d.comments)showComments(d.comments);
 if(d.apply){modal('申请加入这次共创',`<form data-form="apply" data-team-id="${d.apply}"><label>介绍你能带来的技能与可投入时间<textarea name="text" maxlength="400" required placeholder="我擅长……，每周可以投入……"></textarea></label><p class="form-note">演示只保存申请，不会联系真实用户。</p><button class="primary" type="submit">保存加入申请</button></form>`);}
 if(d.product)showProduct(d.product);
 if(d.redeem){const order=redeem(d.redeem);if(order){$('#social-dialog').close();mineTab=products.find(p=>p.id===d.redeem).type==='coupon'?'orders':'dress';navigate('me');toast('兑换成功，积分已扣除');}else toast('余额、库存或拥有状态已变化，请重新查看');}
 if(d.equip&&social.owned.includes(d.equip)){const p=products.find(p=>p.id===d.equip);if(p.type==='frame')social.equipped=p.id;if(p.type==='background')social.background=p.id;save();render();toast('装扮已更新，社区里也能看见你的新风格');}
 if('resetDress' in d){social.equipped='';social.background='';save();render();}
 if(d.cancelOrder){modal('取消这次兑换？',`<p class="modal-description">取消后积分和奖品名额会立即退回。已核销的订单不能取消。</p><button class="primary full" data-confirm-cancel="${d.cancelOrder}">确认取消并退回积分</button>`);}
 if(d.confirmCancel){const ok=cancelOrder(d.confirmCancel);$('#social-dialog').close();render();toast(ok?'订单已取消，积分与名额已退回':'订单状态已变更，无法取消');}
 if(d.useOrder){modal('模拟工作人员核销',`<p class="modal-description">确认后，此演示兑换码将失效，订单不再支持取消。此操作不会兑换真实商品。</p><button class="primary full" data-confirm-use="${d.useOrder}">确认模拟核销</button>`);}
 if(d.confirmUse){const ok=useOrder(d.confirmUse);$('#social-dialog').close();render();toast(ok?'模拟核销完成，兑换码已失效':'此订单不可重复核销');}
 if('editProfile' in d){modal('让同好更容易找到你',`<form data-form="interests"><p class="muted">选择你的兴趣，会展示在个人名片并用于发现共同点。</p><div class="interest-options">${['摄影','音乐','跑步','咖啡','设计','Web3','游戏','电影'].map(t=>`<label><input type="checkbox" name="interest" value="${t}" ${social.interests.includes(t)?'checked':''}>${t}</label>`).join('')}</div><button type="submit" class="primary">保存兴趣</button></form>`);}
 if(d.connectPerson){if(!social.connections.includes(d.connectPerson)&&!social.blocked.includes(d.connectPerson))social.connections.push(d.connectPerson);save();showPerson(d.connectPerson);toast('申请已保存，本 Demo 不会向外发送消息');}
 if(d.block){const i=social.blocked.indexOf(d.block);i<0?social.blocked.push(d.block):social.blocked.splice(i,1);save();showPerson(d.block);render();toast(i<0?'已屏蔽，其动态与招募不再展示':'已取消屏蔽');}
 if(d.report){modal('记录举报',`<form data-form="report" data-user-id="${d.report}"><label>举报原因<select name="reason"><option>骚扰或不友善内容</option><option>虚假招募或广告</option><option>冒用身份</option></select></label><p class="form-note">此演示只在本机记录，不会提交给审核团队。</p><button class="primary" type="submit">保存举报记录</button></form>`);}
 if('privacyManage' in d){modal('我的交流设置',`<h3>已保存的交流申请</h3><p class="modal-description">${social.connections.length?social.connections.map(id=>people[id].name).join('、'):'暂无交流申请'} · 仅本机演示</p><h3>已屏蔽用户</h3>${social.blocked.length?social.blocked.map(id=>`<p class="manage-row">${people[id].name}<button class="outline" data-block="${id}">取消屏蔽</button></p>`).join(''):'<p class="modal-description">暂无屏蔽用户</p>'}`);}
});
document.addEventListener('submit',event=>{const form=event.target;const kind=form.dataset.form;if(!kind)return;event.preventDefault();const fd=new FormData(form);const text=(name)=>String(fd.get(name)||'').trim();
 if(kind==='post'||kind==='team'){if(!text('title')||!text('text')){toast('请填写标题与内容');return;}if(kind==='post'){social.posts.unshift({id:uid(),author:'me',title:text('title'),text:text('text'),circle:text('circle'),art:'',likes:0,event:'',time:'刚刚'});communityTab='feed';circleFilter='';}else{if(!text('skill')||!text('duration')){toast('请填写所需技能与时间投入');return;}social.teams.unshift({id:uid(),author:'me',title:text('title'),description:text('text'),skill:text('skill'),duration:text('duration'),pay:text('pay'),cross:fd.has('cross'),school:'浙江大学'});communityTab='teams';}state.school='all';save();$('#social-dialog').close();navigate('campus');toast('已发布，内容保存在当前浏览器');return;}
 if(kind==='comment'){if(!text('text'))return;(social.comments[form.dataset.postId]??=[]).push(text('text'));save();showComments(form.dataset.postId);render();return;}
 if(kind==='apply'){if(!text('text'))return;social.applications[form.dataset.teamId]=text('text');save();$('#social-dialog').close();render();toast('加入申请已保存，等待演示回应');return;}
 if(kind==='interests'){social.interests=fd.getAll('interest');save();$('#social-dialog').close();render();return;}
 if(kind==='report'){social.reports.push({user:form.dataset.userId,reason:text('reason')});save();$('#social-dialog').close();toast('举报记录已保存在本机');}
});
document.addEventListener('change',e=>{if(e.target.id==='school-privacy'){social.showSchool=e.target.checked;save();render();}});
